INSERT INTO feature VALUES('features-guide','workflow','The features ledger as a guide','features-ledger','implemented','ordinary',NULL,'`ledger list` prints one line per feature, narrowed to an area and a status, and `ledger show <id>` a feature''s row, its exemplars'' sources whole and its corpus paths: what an author reads before writing a form. The Model Context Protocol server answers the same as `ledger_list` and `ledger_show`.','surface-features surface-agentic workflow-ledger-tasks','crates/workflow-ledger-tasks/tests/cli.rs::the_features_ledger_lists_and_shows_1827 crates/surface-agentic/src/connection.rs::the_ledger_tools_read_the_committed_ledger_1827',NULL,NULL);
